function publicDemoSummary(rows, food, transport) {
  const total = rows.reduce((sum, row) => sum + row.amount, 0);
  const budget = food + transport;
  const covered = rows.filter((row) => (row.category === "식비" && food > 0) || (row.category === "교통" && transport > 0)).reduce((sum, row) => sum + row.amount, 0);
  return { total, budget, covered, uncovered: total - covered, remaining: Math.max(0, budget - covered), over: Math.max(0, covered - budget), rate: budget ? Math.round(covered / budget * 100) : null };
}

function publicDemoClient(calculate, rows) {
  const form = document.getElementById("public-demo-form");
  if (!form) return;
  form.hidden = false;
  const food = document.getElementById("demo-food");
  const transport = document.getElementById("demo-transport");
  const status = document.getElementById("demo-status");
  const parse = (value) => {
    const raw = String(value).trim();
    if (!/^(?:\d+|\d{1,3}(?:,\d{3})+)$/.test(raw)) return null;
    const amount = Number(raw.replace(/,/g, ""));
    return Number.isSafeInteger(amount) && amount >= 0 && amount <= 1000000000 ? amount : null;
  };
  const update = () => {
    const f = parse(food.value), t = parse(transport.value);
    food.setAttribute("aria-invalid", String(f === null));
    transport.setAttribute("aria-invalid", String(t === null));
    if (f === null || t === null) {
      status.textContent = "0원부터 10억원까지의 정수를 입력하세요. 쉼표는 세 자리마다 사용할 수 있습니다. 결과는 마지막으로 계산한 값입니다.";
      (f === null ? food : transport).focus();
      return;
    }
    const result = calculate(rows, f, t);
    for (const key of ["total", "budget", "covered", "uncovered", "remaining", "over"]) {
      document.getElementById(`demo-${key}`).textContent = result[key].toLocaleString("ko-KR") + "원";
    }
    document.getElementById("demo-rate").textContent = result.rate === null ? "예산 미설정" : `${result.rate}%`;
    status.textContent = result.rate === null ? "두 분류 모두 예산이 없습니다. 이 예제에는 별도 전체 예산도 없습니다." : `계산했습니다. 예산 적용 사용액 ${result.covered.toLocaleString("ko-KR")}원, 예산 밖 지출 ${result.uncovered.toLocaleString("ko-KR")}원입니다.`;
  };
  form.addEventListener("submit", (event) => { event.preventDefault(); update(); });
  document.getElementById("demo-reset").addEventListener("click", () => { food.value = "300,000"; transport.value = "100,000"; update(); });
}

